insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e1-u1', (select id from public.learn_courses where code = 'math-e1'), '수와 연산, 모양', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-l1', (select id from public.learn_units where code = 'math-e1-u1'), '수 세기', '물건을 하나씩 짚으며 세면 몇 개인지 알 수 있어요. 10이 넘으면 5개나 10개씩 묶어서 세면 쉬워요.', '🍎🍎🍎🍎🍎 → 사과는 5개예요.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-l1'), (select id from public.learn_skills where code = 'm.e1.count') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-l2', (select id from public.learn_units where code = 'math-e1-u1'), '더하기와 빼기', '**더하기(+)**는 두 수를 합치는 것이고, **빼기(-)**는 큰 수에서 작은 수만큼 덜어 내는 것이에요.', '$3 + 4 = 7$, $8 - 3 = 5$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-l2'), (select id from public.learn_skills where code = 'm.e1.addsub') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-l3', (select id from public.learn_units where code = 'math-e1-u1'), '수의 크기 비교', '두 수 중 더 큰 수는 **>**, 더 작은 수는 **<**로 나타내요. 기호는 큰 수 쪽으로 벌어져요.', '$8 > 5$, $4 < 7$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-l3'), (select id from public.learn_skills where code = 'm.e1.cmp') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-l4', (select id from public.learn_units where code = 'math-e1-u1'), '여러 가지 모양', '**삼각형**은 변이 3개, **사각형**은 변이 4개예요. **원**은 둥글고 꼭짓점이 없어요.', '삼각형: 변 3개, 꼭짓점 3개', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-l4'), (select id from public.learn_skills where code = 'm.e1.shape') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-l5', (select id from public.learn_units where code = 'math-e1-u1'), '길이와 시계', '길이는 **cm**로 재요. 시계의 짧은바늘은 ''시'', 긴바늘은 ''분''을 알려 줘요.', '짧은바늘 4, 긴바늘 12 → 4시', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-l5'), (select id from public.learn_skills where code = 'm.e1.measure') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-geo1', (select id from public.learn_units where code = 'math-e1-u1'), '도형의 이름과 꼭짓점', '**삼각형**은 변이 3개, **사각형**은 변이 4개예요. **원**은 둥글고 꼭짓점이 없어요.', '삼각형: 변 3개, 꼭짓점 3개', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-geo1'), (select id from public.learn_skills where code = 'm.e1.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e1-geo2', (select id from public.learn_units where code = 'math-e1-u1'), '입체도형 알아보기', '상자 모양은 **직육면체**, 둥근 기둥 모양은 **원기둥**, 공 모양은 **구**예요.', '직육면체 · 원기둥 · 구', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e1-geo2'), (select id from public.learn_skills where code = 'm.e1.geo2') on conflict do nothing;
