insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e2-u1', (select id from public.learn_courses where code = 'math-e2'), '자릿값, 덧셈 뺄셈, 곱셈 시작', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-l1', (select id from public.learn_units where code = 'math-e2-u1'), '자릿값', '두 자리 수에서 왼쪽 숫자는 **십의 자리**, 오른쪽 숫자는 **일의 자리**예요. 10이 10개 모이면 100이에요.', '$47$ = 10이 4개, 1이 7개', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-l1'), (select id from public.learn_skills where code = 'm.e2.place') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-l2', (select id from public.learn_units where code = 'math-e2-u1'), '두 자리 수의 덧셈과 뺄셈', '일의 자리끼리, 십의 자리끼리 계산해요. 합이 10이 넘으면 올림하고, 뺄 수 없으면 내림해요.', '$45 + 27 = 72$, $61 - 28 = 33$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-l2'), (select id from public.learn_skills where code = 'm.e2.addsub') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-l3', (select id from public.learn_units where code = 'math-e2-u1'), '곱셈 처음 만나기', '같은 수를 여러 번 더하는 것을 **곱셈(×)**으로 짧게 쓸 수 있어요.', '$3 + 3 + 3 + 3 = 3 \times 4 = 12$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-l3'), (select id from public.learn_skills where code = 'm.e2.mul') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-l4', (select id from public.learn_units where code = 'math-e2-u1'), '길이와 시각', '**1m = 100cm**예요. 시계에서 긴바늘이 숫자 하나를 지날 때마다 5분이 지나요.', '긴바늘이 6 → 30분', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-l4'), (select id from public.learn_skills where code = 'm.e2.time') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-l5', (select id from public.learn_units where code = 'math-e2-u1'), '규칙 찾기', '수가 늘어나거나 줄어드는 **규칙**을 찾으면 다음 수를 알 수 있어요.', '$2, 4, 6, 8, \square$ → 2씩 커져요, □ = 10', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-l5'), (select id from public.learn_skills where code = 'm.e2.pattern') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-geo1', (select id from public.learn_units where code = 'math-e2-u1'), '삼각형과 사각형', '**삼각형**은 곧은 변 3개와 꼭짓점 3개, **사각형**은 곧은 변 4개와 꼭짓점 4개가 있어요. 모양이 달라도 변의 수와 꼭짓점의 수는 같아요.', '사각형: 변 4개, 꼭짓점 4개', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-geo1'), (select id from public.learn_skills where code = 'm.e2.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-geo2', (select id from public.learn_units where code = 'math-e2-u1'), '길이와 시각', '자의 눈금 0에 맞추면 다른 쪽 끝의 눈금이 길이예요. $1\text{ m}=100\text{ cm}$예요. 시계의 긴바늘이 가리키는 숫자에 5를 곱하면 분이에요.', '2 m 30 cm = 230 cm', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-geo2'), (select id from public.learn_skills where code = 'm.e2.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e2-dat1', (select id from public.learn_units where code = 'math-e2-u1'), '분류하고 표와 그래프로 나타내기', '자료를 기준에 따라 나누어 세고, **표**나 **그래프**로 나타내면 한눈에 비교할 수 있어요.', 'A 3명, B 5명, C 2명 → 모두 10명', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e2-dat1'), (select id from public.learn_skills where code = 'm.e2.dat1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e3-u1', (select id from public.learn_courses where code = 'math-e3'), '곱셈과 나눗셈, 분수, 측정, 도형, 자료', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-l1', (select id from public.learn_units where code = 'math-e3-u1'), '곱셈과 나눗셈', '곱셈은 같은 수를 여러 번 더하는 것이고, **나눗셈**은 똑같이 나누는 것이에요. 곱셈구구를 알면 나눗셈도 쉬워요.', '$6 \times 7 = 42$, $42 \div 6 = 7$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-l1'), (select id from public.learn_skills where code = 'm.e3.muldiv') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-l2', (select id from public.learn_units where code = 'math-e3-u1'), '분수 알아보기', '전체를 똑같이 나눈 것 중의 일부를 **분수**로 나타내요. 아래 수가 **분모**, 위의 수가 **분자**예요.', '$\frac{3}{8}$ : 8조각 중 3조각', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-l2'), (select id from public.learn_skills where code = 'm.e3.frac') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-l3', (select id from public.learn_units where code = 'math-e3-u1'), '길이·들이·무게', '**1km = 1000m**, **1L = 1000mL**, **1kg = 1000g**예요. 단위를 바꿀 때는 1000을 곱해요.', '$3\text{km} = 3000\text{m}$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-l3'), (select id from public.learn_skills where code = 'm.e3.unit') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-l4', (select id from public.learn_units where code = 'math-e3-u1'), '원과 각', '**직각**은 90°예요. 원에서 **지름**은 **반지름**의 2배예요.', '반지름 5cm → 지름 10cm', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-l4'), (select id from public.learn_skills where code = 'm.e3.geo') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-l5', (select id from public.learn_units where code = 'math-e3-u1'), '표와 그래프', '조사한 결과를 표로 정리하면 가장 많은 것, 가장 적은 것, 합계를 쉽게 알 수 있어요.', '$7 + 5 + 9 + 4 = 25$명', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-l5'), (select id from public.learn_skills where code = 'm.e3.data') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-geo1', (select id from public.learn_units where code = 'math-e3-u1'), '각과 직각', '한 점에서 시작하는 두 반직선이 이루는 도형을 **각**이라고 해요. $90^\circ$인 각은 **직각**, 더 작으면 **예각**, 더 크면 **둔각**이에요.', '$30^\circ$ 예각 · $90^\circ$ 직각 · $120^\circ$ 둔각', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-geo1'), (select id from public.learn_skills where code = 'm.e3.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-geo2', (select id from public.learn_units where code = 'math-e3-u1'), '원의 반지름과 지름', '원의 중심에서 원 위의 한 점까지의 길이가 **반지름**, 중심을 지나는 선분이 **지름**이에요. 지름은 반지름의 2배예요.', '반지름 5 cm → 지름 10 cm', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-geo2'), (select id from public.learn_skills where code = 'm.e3.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e3-ari1', (select id from public.learn_units where code = 'math-e3-u1'), '세 자리 수의 덧셈과 뺄셈', '일의 자리부터 차례로 계산해요. 더해서 10이 넘으면 윗자리로 **받아올림**하고, 뺄 수 없으면 윗자리에서 **받아내림**해요.', '346+278=624', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e3-ari1'), (select id from public.learn_skills where code = 'm.e3.ari1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e4-u1', (select id from public.learn_courses where code = 'math-e4'), '큰 수, 곱셈과 나눗셈, 분수와 소수, 각도, 그래프', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-l1', (select id from public.learn_units where code = 'math-e4-u1'), '큰 수', '만(10000) 단위로 큰 수를 읽고 써요. 각 자리의 숫자는 **자릿값**만큼의 크기를 나타내요.', '$5 \times 10000 + 3 \times 1000 = 53000$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-l1'), (select id from public.learn_skills where code = 'm.e4.big') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-l2', (select id from public.learn_units where code = 'math-e4-u1'), '큰 수의 곱셈과 나눗셈', '곱하는 수를 나누어 곱한 뒤 더해요. 나눗셈은 몫을 어림해서 확인해요.', '$34 \times 12 = 408$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-l2'), (select id from public.learn_skills where code = 'm.e4.muldiv') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-l3', (select id from public.learn_units where code = 'math-e4-u1'), '분수와 소수의 덧셈·뺄셈', '분모가 같은 분수는 **분자끼리** 더하고 빼요. 소수는 소수점의 자리를 맞춰 계산해요.', '$\frac{3}{5} + \frac{1}{5} = \frac{4}{5}$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-l3'), (select id from public.learn_skills where code = 'm.e4.frac') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-l4', (select id from public.learn_units where code = 'math-e4-u1'), '각도와 도형', '삼각형의 세 각의 합은 **180°**, 사각형의 네 각의 합은 **360°**예요.', '$180 - 50 - 60 = 70$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-l4'), (select id from public.learn_skills where code = 'm.e4.angle') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-l5', (select id from public.learn_units where code = 'math-e4-u1'), '막대그래프와 평균', '자료를 읽어 합계와 차를 구해요. **평균**은 모두 더한 값을 개수로 나눈 값이에요.', '$60 \div 4 = 15$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-l5'), (select id from public.learn_skills where code = 'm.e4.data') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-geo1', (select id from public.learn_units where code = 'math-e4-u1'), '도형의 각의 크기', '삼각형의 세 각의 합은 $180^\circ$, 사각형의 네 각의 합은 $360^\circ$예요.', '$50^\circ+60^\circ+70^\circ=180^\circ$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-geo1'), (select id from public.learn_skills where code = 'm.e4.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-geo2', (select id from public.learn_units where code = 'math-e4-u1'), '사각형과 다각형', '마주 보는 한 쌍의 변이 평행하면 **사다리꼴**, 두 쌍이 모두 평행하면 **평행사변형**, 네 변이 모두 같으면 **마름모**예요. 이웃하지 않는 꼭짓점을 이은 선분이 **대각선**이에요.', '사각형의 대각선: 2개', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-geo2'), (select id from public.learn_skills where code = 'm.e4.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e4-dat1', (select id from public.learn_units where code = 'math-e4-u1'), '꺾은선그래프 읽기', '**꺾은선그래프**는 시간에 따라 변하는 값을 점과 선으로 나타내요. 선이 오르면 늘어난 것, 내리면 줄어든 것이에요.', '1일 12 → 3일 20: 8 늘었어요', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e4-dat1'), (select id from public.learn_skills where code = 'm.e4.dat1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e5-u1', (select id from public.learn_courses where code = 'math-e5'), '분수, 소수, 약수와 배수, 넓이와 부피, 비율', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-l1', (select id from public.learn_units where code = 'math-e5-u1'), '분모가 다른 분수의 덧셈·뺄셈', '분모가 다르면 먼저 **통분**해요. 두 분모의 최소공배수를 공통분모로 쓰면 편해요.', '$\frac{1}{2} + \frac{1}{3} = \frac{3}{6} + \frac{2}{6} = \frac{5}{6}$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-l1'), (select id from public.learn_skills where code = 'm.e5.frac') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-l2', (select id from public.learn_units where code = 'math-e5-u1'), '소수의 곱셈', '소수점을 없애고 자연수처럼 곱한 뒤, 곱해진 소수점 아래 자리 수만큼 소수점을 다시 찍어요.', '$0.6 \times 4 = 2.4$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-l2'), (select id from public.learn_skills where code = 'm.e5.dec') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-l3', (select id from public.learn_units where code = 'math-e5-u1'), '약수와 배수', '**약수**는 어떤 수를 나누어떨어지게 하는 수, **배수**는 그 수를 1배, 2배, 3배... 한 수예요.', '12의 약수: 1, 2, 3, 4, 6, 12', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-l3'), (select id from public.learn_skills where code = 'm.e5.factor') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-l4', (select id from public.learn_units where code = 'math-e5-u1'), '넓이와 부피', '직사각형은 **가로 × 세로**, 삼각형은 **밑변 × 높이 ÷ 2**, 직육면체의 부피는 **가로 × 세로 × 높이**예요.', '$8 \times 5 = 40$ cm²', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-l4'), (select id from public.learn_skills where code = 'm.e5.area') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-l5', (select id from public.learn_units where code = 'math-e5-u1'), '비와 비율', '**비율**은 비교하는 양을 기준량으로 나눈 값이에요. 비율에 100을 곱하면 **백분율(%)**이에요.', '$3 : 5 \to 3 \div 5 = 0.6$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-l5'), (select id from public.learn_skills where code = 'm.e5.ratio') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-geo1', (select id from public.learn_units where code = 'math-e5-u1'), '둘레와 넓이', '직사각형: 넓이=가로×세로, 삼각형: 밑변×높이÷2, 평행사변형: 밑변×높이, 사다리꼴: (윗변+아랫변)×높이÷2, 마름모: 대각선×대각선÷2.', '삼각형 밑변 10, 높이 6 → 10×6÷2=30', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-geo1'), (select id from public.learn_skills where code = 'm.e5.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-geo2', (select id from public.learn_units where code = 'math-e5-u1'), '합동과 대칭', '모양과 크기가 같아 포개어지는 두 도형을 **합동**이라고 해요. 한 직선으로 접었을 때 완전히 겹치는 도형은 **선대칭도형**이고 그 직선이 **대칭축**이에요.', '정사각형의 대칭축: 4개', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-geo2'), (select id from public.learn_skills where code = 'm.e5.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-dat1', (select id from public.learn_units where code = 'math-e5-u1'), '평균 구하기', '**평균**은 자료를 모두 더한 값을 자료의 개수로 나눈 값이에요.', '(4+6+8+10)÷4=7', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-dat1'), (select id from public.learn_skills where code = 'm.e5.dat1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e5-dat2', (select id from public.learn_units where code = 'math-e5-u1'), '가능성', '어떤 일이 일어날 **가능성**은 0(불가능)에서 1(확실) 사이의 수로 나타내요. 가능성=(원하는 경우의 수)÷(전체 경우의 수).', 'A 공 3개, B 공 2개 → A일 가능성 $\frac{3}{5}=0.6$', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e5-dat2'), (select id from public.learn_skills where code = 'm.e5.dat2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-e6-u1', (select id from public.learn_courses where code = 'math-e6'), '분수·소수의 연산, 비례, 백분율, 원과 부피, 평균', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-l1', (select id from public.learn_units where code = 'math-e6-u1'), '분수·소수의 곱셈과 나눗셈', '분수의 곱셈은 분자끼리, 분모끼리 곱해요. 분수의 나눗셈은 **역수**를 곱해요.', '$\frac{3}{4} \times \frac{2}{5} = \frac{3}{10}$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-l1'), (select id from public.learn_skills where code = 'm.e6.frac') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-l2', (select id from public.learn_units where code = 'math-e6-u1'), '비례식과 비례배분', '비례식에서는 **안쪽 수의 곱 = 바깥쪽 수의 곱**이에요. 전체를 비로 나누면 **비례배분**이에요.', '$3 : 4 = 12 : \square \to \square = 16$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-l2'), (select id from public.learn_skills where code = 'm.e6.ratio') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-l3', (select id from public.learn_units where code = 'math-e6-u1'), '백분율', '**백분율(%)**은 기준량을 100으로 보았을 때의 비율이에요. 소수에 100을 곱하면 %가 돼요.', '80의 25% = $80 \times 25 \div 100 = 20$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-l3'), (select id from public.learn_skills where code = 'm.e6.pct') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-l4', (select id from public.learn_units where code = 'math-e6-u1'), '원과 입체도형', '원의 둘레는 **지름 × 3.14**, 원의 넓이는 **반지름 × 반지름 × 3.14**예요.', '$10 \times 3.14 = 31.4$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-l4'), (select id from public.learn_skills where code = 'm.e6.geo') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-l5', (select id from public.learn_units where code = 'math-e6-u1'), '평균과 자료 정리', '**평균**은 합 ÷ 개수, **중앙값**은 한가운데 수, **최빈값**은 가장 많이 나온 수예요.', '$(80 + 90 + 70 + 100) \div 4 = 85$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-l5'), (select id from public.learn_skills where code = 'm.e6.stat') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-geo1', (select id from public.learn_units where code = 'math-e6-u1'), '원주와 원의 넓이', '원주(원의 둘레)=지름×원주율, 원의 넓이=반지름×반지름×원주율이에요. 원주율은 약 $3.14$예요.', '반지름 5 cm → 둘레 $10\times3.14=31.4$ cm', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-geo1'), (select id from public.learn_skills where code = 'm.e6.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-geo2', (select id from public.learn_units where code = 'math-e6-u1'), '직육면체와 정육면체', '부피=가로×세로×높이, 겉넓이=(세 면의 넓이의 합)×2예요. 직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.', '$6\times4\times3=72$ cm³', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-geo2'), (select id from public.learn_skills where code = 'm.e6.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-dat1', (select id from public.learn_units where code = 'math-e6-u1'), '띠그래프와 원그래프', '**띠그래프**와 **원그래프**는 전체를 100%로 보고 각 부분의 비율을 나타내요. 부분의 수=전체×비율.', '전체 200명의 25% → 50명', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-dat1'), (select id from public.learn_skills where code = 'm.e6.dat1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-ari1', (select id from public.learn_units where code = 'math-e6-u1'), '자연수의 혼합 계산', '덧셈·뺄셈·곱셈·나눗셈이 섞여 있으면 **괄호 안**을 먼저, 그다음 **곱셈과 나눗셈**, 마지막으로 **덧셈과 뺄셈**을 앞에서부터 계산해요.', '12+3×4=12+12=24', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-ari1'), (select id from public.learn_skills where code = 'm.e6.ari1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-e6-ari2', (select id from public.learn_units where code = 'math-e6-u1'), '올림, 버림, 반올림', '**올림**은 구하려는 자리 아래를 모두 올려 주고, **버림**은 모두 버려요. **반올림**은 바로 아래 자리가 5 이상이면 올리고 4 이하이면 버려요.', '3472를 100 단위로 올림 3500, 버림 3400, 반올림 3500', 9, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-e6-ari2'), (select id from public.learn_skills where code = 'm.e6.ari2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-m1-linear-eq', (select id from public.learn_courses where code = 'math-m1-algebra'), '일차방정식', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '식의 값 구하기', '문자에 수를 넣는 것을 **대입**이라고 해요. 대입해서 계산한 결과가 **식의 값**이에요. 음수를 넣을 때는 괄호를 써서 실수를 줄여요.', '$x=3$일 때 $2x+1$ 은 $2\times3+1=7$ 이에요.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l1'), (select id from public.learn_skills where code = 'm.expr') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l2', (select id from public.learn_units where code = 'math-m1-linear-eq'), '등식의 성질', '등식은 **저울**과 같아요. 양변에 같은 수를 더하거나 빼고, 곱하거나(0이 아닌 수로) 나누어도 저울은 평형을 유지해요.', '$x+5=9$ 의 양변에서 $5$를 빼면 $x=4$ 예요.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l2'), (select id from public.learn_skills where code = 'm.prop') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l3', (select id from public.learn_units where code = 'math-m1-linear-eq'), '일차방정식 풀기', '$x$가 있는 항은 한쪽, 숫자는 반대쪽으로 **이항**해서 모아요. 이항하면 부호가 바뀌어요. 마지막으로 $x$ 앞의 수로 나누면 끝!', '$2x+1=9 \Rightarrow 2x=8 \Rightarrow x=4$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l3'), (select id from public.learn_skills where code = 'm.solve') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l4', (select id from public.learn_units where code = 'math-m1-linear-eq'), '방정식으로 문제 풀기', '문장제는 **구하려는 것을 $x$로 놓고** → 문장을 식으로 옮기고 → 풀고 → 답이 조건에 맞는지 확인하는 순서로 풀어요.', '어떤 수의 $3$배에 $2$를 더하면 $14$ → $3x+2=14$ → $x=4$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l4'), (select id from public.learn_skills where code = 'm.word') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-geo1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '각의 성질과 다각형', '맞꼭지각은 같고, 평행선에서 동위각·엇각은 같아요. $n$각형의 내각의 합은 $180^\circ\times(n-2)$예요.', '오각형: $180^\circ\times3=540^\circ$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-geo1'), (select id from public.learn_skills where code = 'm.m1.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-geo2', (select id from public.learn_units where code = 'math-m1-linear-eq'), '부채꼴과 입체도형의 측정', '호의 길이 $=2\pi r\times\frac{a}{360}$, 부채꼴의 넓이 $=\pi r^2\times\frac{a}{360}$, 구의 부피 $=\frac43\pi r^3$, 원뿔의 부피 $=\frac13\pi r^2h$예요.', '$r=3$인 구: $\frac43\pi\times27=36\pi$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-geo2'), (select id from public.learn_skills where code = 'm.m1.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-neg1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '정수와 유리수의 계산', '같은 부호의 두 수를 더하면 절댓값을 더하고, 다른 부호이면 절댓값의 차에 큰 쪽의 부호를 붙여요. 곱셈과 나눗셈은 부호가 같으면 +, 다르면 −예요.', '$(-3)+5=2$, $(-6)\times4=-24$', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-neg1'), (select id from public.learn_skills where code = 'm.m1.neg1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-fac1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '소인수분해와 최대공약수·최소공배수', '자연수를 소수의 곱으로 나타내는 것이 **소인수분해**예요. 공통인 약수 중 가장 큰 수가 **최대공약수**, 공통인 배수 중 가장 작은 수가 **최소공배수**예요.', '$72=2^3\times3^2$', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-fac1'), (select id from public.learn_skills where code = 'm.m1.fac1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-crd1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '좌표평면', '점의 위치는 (x좌표, y좌표)로 나타내요. 부호에 따라 제1~4사분면이 정해지고, x축에 대한 대칭이동은 y좌표의 부호가 바뀌어요.', '(−2, 5)는 제2사분면', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-crd1'), (select id from public.learn_skills where code = 'm.m1.crd1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-prp1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '정비례와 반비례', '**정비례**는 y=ax, **반비례**는 $y=\frac{a}{x}$ 꼴이에요. 정비례에서는 y÷x가, 반비례에서는 x×y가 일정해요.', 'x=2일 때 y=6인 정비례: y=3x', 9, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-prp1'), (select id from public.learn_skills where code = 'm.m1.prp1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m1-sta1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '대푯값과 상대도수', '**중앙값**은 크기순으로 나열한 가운데 값, **최빈값**은 가장 많이 나온 값이에요. **상대도수**=(도수)÷(전체 도수).', '1, 3, 5, 7, 9의 중앙값은 5', 10, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m1-sta1'), (select id from public.learn_skills where code = 'm.m1.sta1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-m2-unit', (select id from public.learn_courses where code = 'math-m2-functions-probability'), '중2 수학', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-l1', (select id from public.learn_units where code = 'math-m2-unit'), '지수법칙과 다항식', '밑이 같은 곱은 지수를 더하고, 거듭제곱의 거듭제곱은 지수를 곱해요. 다항식은 같은 문자 항끼리 모아 계산해요.', '$x^2\times x^3=x^5$, $(x^2)^3=x^6$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-l1'), (select id from public.learn_skills where code = 'm.m2.exp') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-l2', (select id from public.learn_units where code = 'math-m2-unit'), '연립일차방정식', '두 식에서 한 문자를 없애 해를 구해요. 가감법과 대입법을 상황에 맞게 골라요.', '$x+y=5,\ x-y=1 \Rightarrow x=3,\ y=2$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-l2'), (select id from public.learn_skills where code = 'm.m2.sys') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-l3', (select id from public.learn_units where code = 'math-m2-unit'), '일차부등식', '등식의 성질과 비슷하게 풀되, 음수를 곱하거나 나누면 부등호의 방향이 바뀌어요.', '$-2x>6 \Rightarrow x<-3$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-l3'), (select id from public.learn_skills where code = 'm.m2.ineq') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-l4', (select id from public.learn_units where code = 'math-m2-unit'), '일차함수와 그래프', '$y=ax+b$ 에서 $a$는 기울기, $b$는 $y$절편이에요. 평행한 직선은 기울기가 같아요.', '기울기 $=\dfrac{y\text{의 증가량} }{x\text{의 증가량} }$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-l4'), (select id from public.learn_skills where code = 'm.m2.func') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-l5', (select id from public.learn_units where code = 'math-m2-unit'), '경우의 수와 확률', '확률은 (일어나는 경우의 수)÷(모든 경우의 수)예요. 동시에 일어나는 독립 사건은 곱하고, ''적어도''는 여사건을 써요.', '$P(A)=1-P(A^c)$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-l5'), (select id from public.learn_skills where code = 'm.m2.prob') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-geo1', (select id from public.learn_units where code = 'math-m2-unit'), '삼각형과 사각형의 성질', '이등변삼각형의 두 밑각은 같아요. 평행사변형에서 이웃한 두 각의 합은 $180^\circ$이고, 삼각형의 두 변의 중점을 이은 선분은 나머지 변의 $\frac12$이에요.', '밑각 $50^\circ$ → 꼭지각 $80^\circ$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-geo1'), (select id from public.learn_skills where code = 'm.m2.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-geo2', (select id from public.learn_units where code = 'math-m2-unit'), '닮음과 피타고라스 정리', '닮은 도형은 대응하는 변의 비가 같고 넓이의 비는 닮음비의 제곱이에요. 직각삼각형에서 $a^2+b^2=c^2$이에요.', '$3^2+4^2=5^2$', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-geo2'), (select id from public.learn_skills where code = 'm.m2.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-rec1', (select id from public.learn_units where code = 'math-m2-unit'), '순환소수', '소수점 아래에서 같은 숫자가 계속 반복되는 소수를 **순환소수**라 하고 반복되는 부분을 **순환마디**라 해요. 기약분수의 분모가 2나 5뿐이면 유한소수예요.', '$\frac{1}{3}=0.\dot{3}$', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-rec1'), (select id from public.learn_skills where code = 'm.m2.rec1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m2-lfn1', (select id from public.learn_units where code = 'math-m2-unit'), '일차함수와 일차방정식', '일차함수 y=ax+b에서 a는 기울기, b는 y절편이에요. 두 그래프의 교점은 두 식을 연립한 해예요.', 'y=2x−6의 x절편은 3', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m2-lfn1'), (select id from public.learn_skills where code = 'm.m2.lfn1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-m3-unit', (select id from public.learn_courses where code = 'math-m3-roots-quadratics-trig'), '중3 수학', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-l1', (select id from public.learn_units where code = 'math-m3-unit'), '제곱근과 실수', '$\sqrt{a}$ 는 제곱하여 $a$가 되는 음이 아닌 수예요. 근호 안의 제곱수는 밖으로 꺼내고, 분모의 근호는 유리화해요.', '$\sqrt{72}=6\sqrt{2}$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-l1'), (select id from public.learn_skills where code = 'm.m3.sqrt') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-l2', (select id from public.learn_units where code = 'math-m3-unit'), '곱셈 공식과 인수분해', '$(a+b)^2=a^2+2ab+b^2$, $(a+b)(a-b)=a^2-b^2$. 인수분해는 곱셈 공식을 거꾸로 쓰는 일이에요.', '$x^2+5x+6=(x+2)(x+3)$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-l2'), (select id from public.learn_skills where code = 'm.m3.fact') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-l3', (select id from public.learn_units where code = 'math-m3-unit'), '이차방정식', '인수분해로 $AB=0$ 꼴을 만들어 풀어요. 판별식 $D=b^2-4ac$ 로 근의 개수를 알 수 있고, 근과 계수의 관계도 쓸 수 있어요.', '$x^2-5x+6=0 \Rightarrow x=2$ 또는 $3$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-l3'), (select id from public.learn_skills where code = 'm.m3.quad') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-l4', (select id from public.learn_units where code = 'math-m3-unit'), '이차함수와 그래프', '$y=a(x-p)^2+q$ 의 꼭짓점은 $(p,\ q)$, $a$의 부호가 볼록한 방향을 정해요. 완전제곱식으로 바꾸면 꼭짓점을 찾을 수 있어요.', '$y=x^2-4x+3=(x-2)^2-1$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-l4'), (select id from public.learn_skills where code = 'm.m3.qfunc') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-l5', (select id from public.learn_units where code = 'math-m3-unit'), '삼각비', '직각삼각형에서 $\sin A=\frac{\text{대변} }{\text{빗변} }$, $\cos A=\frac{\text{밑변} }{\text{빗변} }$, $\tan A=\frac{\text{대변} }{\text{밑변} }$ 예요.', '$\sin 30^\circ=\dfrac12,\ \cos 60^\circ=\dfrac12$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-l5'), (select id from public.learn_skills where code = 'm.m3.trig') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-geo1', (select id from public.learn_units where code = 'math-m3-unit'), '삼각비', '직각삼각형에서 $\sin A$는 (높이)÷(빗변), $\cos A$는 (밑변)÷(빗변), $\tan A$는 (높이)÷(밑변)이에요.', '3-4-5 삼각형: $\sin A=0.6$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-geo1'), (select id from public.learn_skills where code = 'm.m3.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-geo2', (select id from public.learn_units where code = 'math-m3-unit'), '원의 성질', '한 호에 대한 원주각은 중심각의 $\frac12$이에요. 접선은 반지름과 수직이고, 원에 내접하는 사각형의 대각의 합은 $180^\circ$예요.', '중심각 $100^\circ$ → 원주각 $50^\circ$', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-geo2'), (select id from public.learn_skills where code = 'm.m3.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-m3-sta1', (select id from public.learn_units where code = 'math-m3-unit'), '분산과 표준편차', '**편차**=(변량)−(평균)이에요. **분산**은 편차의 제곱의 평균이고, **표준편차**는 분산의 양의 제곱근이에요. 값이 클수록 자료가 평균에서 멀리 흩어져 있어요.', '2, 4, 6, 8 → 평균 5, 분산 5', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-m3-sta1'), (select id from public.learn_skills where code = 'm.m3.sta1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-h1-unit', (select id from public.learn_courses where code = 'math-h1-common-math-1'), '고1 수학', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-l1', (select id from public.learn_units where code = 'math-h1-unit'), '다항식의 나눗셈과 나머지정리', '$P(x)$ 를 $x-a$ 로 나눈 나머지는 $P(a)$ 이고, $P(a)=0$ 이면 $x-a$ 는 인수예요.', '$x^2+3x+2$ 를 $x-1$ 로 나눈 나머지 $=P(1)=6$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-l1'), (select id from public.learn_skills where code = 'm.h1.poly') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-l2', (select id from public.learn_units where code = 'math-h1-unit'), '복소수와 이차방정식의 판별', '$i^2=-1$ 이고, 판별식 $D=b^2-4ac<0$ 이면 허근을 가져요. 실계수 이차방정식의 허근은 켤레복소수끼리 쌍으로 나타나요.', '$(1+2i)(3-i)=5+5i$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-l2'), (select id from public.learn_skills where code = 'm.h1.cplx') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-l3', (select id from public.learn_units where code = 'math-h1-unit'), '이차부등식', '이차함수의 그래프와 $x$축의 위치로 해를 읽어요. $(x-a)(x-b)<0$ 은 두 근 사이, $>0$ 은 두 근 바깥이에요.', '$x^2-4x+3<0 \Rightarrow 1<x<3$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-l3'), (select id from public.learn_skills where code = 'm.h1.ineq') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-l4', (select id from public.learn_units where code = 'math-h1-unit'), '순열과 조합', '순서를 생각하면 순열 $_nP_r$, 생각하지 않으면 조합 $_nC_r$ 이에요. ''적어도 하나''는 전체에서 여사건을 빼요.', '$_5P_2=20,\ _5C_2=10$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-l4'), (select id from public.learn_skills where code = 'm.h1.comb') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-l5', (select id from public.learn_units where code = 'math-h1-unit'), '직선과 원의 방정식', '점과 직선 사이의 거리 $\frac{|ax_0+by_0+c|}{\sqrt{a^2+b^2} }$, 원 $(x-a)^2+(y-b)^2=r^2$, 접선은 반지름에 수직이에요.', '원 $x^2+y^2=25$ 위의 점 $(3,\ 4)$ 에서의 접선의 기울기 $=-\frac34$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-l5'), (select id from public.learn_skills where code = 'm.h1.geom') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-geo1', (select id from public.learn_units where code = 'math-h1-unit'), '좌표평면 위의 도형', '두 점 사이의 거리 $\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}$, 중점은 좌표의 평균, 기울기는 $\frac{y_2-y_1}{x_2-x_1}$이에요.', 'A(0,0), B(3,4): 거리 5', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-geo1'), (select id from public.learn_skills where code = 'm.h1.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-geo2', (select id from public.learn_units where code = 'math-h1-unit'), '원의 방정식', '중심이 $(a, b)$이고 반지름이 $r$인 원의 방정식은 $(x-a)^2+(y-b)^2=r^2$이에요. 점 $(x_0,y_0)$과 직선 $ax+by+c=0$ 사이의 거리는 $\frac{|ax_0+by_0+c|}{\sqrt{a^2+b^2} }$예요.', '$(x-2)^2+(y-3)^2=25$: 중심 $(2,3)$, 반지름 5', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-geo2'), (select id from public.learn_skills where code = 'm.h1.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-mat1', (select id from public.learn_units where code = 'math-h1-unit'), '행렬의 뜻과 연산', '**행렬**은 수를 직사각형 모양으로 배열한 것이에요. 덧셈·뺄셈·실수배는 같은 위치의 성분끼리 계산하고, 곱 $AB$의 (i, j) 성분은 $A$의 i행과 $B$의 j열의 성분을 차례로 곱해 더한 값이에요.', '$\begin{pmatrix}1&2\\3&4\end{pmatrix}\begin{pmatrix}2&0\\1&3\end{pmatrix}$의 (1, 1) 성분 $=1\times2+2\times1=4$', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-mat1'), (select id from public.learn_skills where code = 'm.h1.mat1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-set1', (select id from public.learn_units where code = 'math-h1-unit'), '집합과 명제', '$n(A\cup B)=n(A)+n(B)-n(A\cap B)$이고, 원소가 n개인 집합의 부분집합은 $2^n$개예요. 명제 ''p이면 q이다''의 대우는 원래 명제와 참, 거짓이 같지만 역은 그렇지 않을 수 있어요.', '$A=\{1,2,3,4\},\ B=\{3,4,5\}$이면 $A\cap B=\{3,4\}$, $A\cup B=\{1,2,3,4,5\}$', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-set1'), (select id from public.learn_skills where code = 'm.h1.set1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-fnc1', (select id from public.learn_units where code = 'math-h1-unit'), '합성함수와 역함수', '합성함수 $(g\circ f)(x)=g(f(x))$는 안쪽 함수부터 계산해요. 역함수는 $f(x)=y$일 때 $f^{-1}(y)=x$인 함수예요.', '$f(x)=2x+1,\ g(x)=x^2$이면 $(g\circ f)(2)=g(5)=25$', 9, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-fnc1'), (select id from public.learn_skills where code = 'm.h1.fnc1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h1-pol1', (select id from public.learn_units where code = 'math-h1-unit'), '인수분해와 삼·사차방정식', '삼차·사차방정식은 조립제법이나 치환을 이용해 **인수분해**한 뒤, 각 인수가 0이 되는 값을 구해 풀어요. 이차 인수는 판별식으로 실근이 있는지 확인해요.', '$x^3-7x+6=(x-1)(x-2)(x+3)=0$이면 $x=1,\ 2,\ -3$', 10, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h1-pol1'), (select id from public.learn_skills where code = 'm.h1.pol1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-h2-unit', (select id from public.learn_courses where code = 'math-h2-algebra-calculus-1'), '고2 수학', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-l1', (select id from public.learn_units where code = 'math-h2-unit'), '지수와 로그', '$\log_a b=x \iff a^x=b$. 로그의 합은 진수의 곱, 차는 진수의 나눗셈이에요. 지수적 증가는 $a\cdot r^t$ 로 나타내요.', '$\log_2 8+\log_2 4=\log_2 32=5$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-l1'), (select id from public.learn_skills where code = 'm.h2.log') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-l2', (select id from public.learn_units where code = 'math-h2-unit'), '삼각함수', '$\pi$ 라디안 $=180^\circ$. 사분면마다 $\sin,\ \cos,\ \tan$ 의 부호가 달라요. $y=a\sin bx+c$ 는 최댓값 $|a|+c$, 주기 $\frac{2\pi}{|b|}$ 예요.', '$\dfrac{\pi}{6}=30^\circ$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-l2'), (select id from public.learn_skills where code = 'm.h2.trig') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-l3', (select id from public.learn_units where code = 'math-h2-unit'), '등차수열과 등비수열', '$a_n=a+(n-1)d$, $a_n=ar^{n-1}$. 등차수열의 합은 $S_n=\frac{n(a+l)}{2}$ 예요.', '$2,\ 5,\ 8,\ \cdots$ 의 제10항 $=29$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-l3'), (select id from public.learn_skills where code = 'm.h2.seq') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-l4', (select id from public.learn_units where code = 'math-h2-unit'), '함수의 극한과 연속', '$\frac00$ 꼴은 인수분해해 약분하고, $x\to\infty$ 에서는 최고차항으로 나눠요. 연속이면 좌극한·우극한·함숫값이 모두 같아요.', '$\lim_{x\to 3}\frac{x^2-9}{x-3}=6$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-l4'), (select id from public.learn_skills where code = 'm.h2.lim') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-l5', (select id from public.learn_units where code = 'math-h2-unit'), '미분과 그 활용', '$(x^n)''=nx^{n-1}$. $f''(a)$ 는 접선의 기울기이고, $f''$ 의 부호로 증가·감소와 극값을 알 수 있어요. 속도는 위치의 도함수예요.', '$(x^3-3x)''=3x^2-3$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-l5'), (select id from public.learn_skills where code = 'm.h2.der') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-geo1', (select id from public.learn_units where code = 'math-h2-unit'), '삼각형과 삼각함수', '사인법칙 $\frac{a}{\sin A}=2R$, 코사인법칙 $c^2=a^2+b^2-2ab\cos C$, 삼각형의 넓이 $\frac12ab\sin C$예요.', '$a=5,b=8,C=60^\circ$ → $c=7$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-geo1'), (select id from public.learn_skills where code = 'm.h2.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-geo2', (select id from public.learn_units where code = 'math-h2-unit'), '호도법과 부채꼴', '$180^\circ=\pi$ 라디안이에요. 반지름 $r$, 중심각 $\theta$(라디안)인 부채꼴의 호의 길이는 $r\theta$, 넓이는 $\frac12r^2\theta$예요.', '$60^\circ=\frac{\pi}{3}$', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-geo2'), (select id from public.learn_skills where code = 'm.h2.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h2-seq1', (select id from public.learn_units where code = 'math-h2-unit'), '수열의 합과 ∑', '$\sum_{k=1}^{n} a_k$는 $a_1+a_2+\cdots+a_n$을 뜻해요. $\sum k=\frac{n(n+1)}{2}$, $\sum c=cn$, $\sum(a_k+b_k)=\sum a_k+\sum b_k$예요.', '$\sum_{k=1}^{4}(2k+1)=3+5+7+9=24$', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h2-seq1'), (select id from public.learn_skills where code = 'm.h2.seq1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-h3-unit', (select id from public.learn_courses where code = 'math-h3-calculus-statistics'), '고3 수학', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-l1', (select id from public.learn_units where code = 'math-h3-unit'), '부정적분과 정적분', '$\int x^n dx=\frac{x^{n+1} }{n+1}+C$, $\int_a^b f(x)dx=F(b)-F(a)$. 위끝·아래끝을 바꾸면 부호가 바뀌고, 구간은 나눌 수 있어요.', '$\int_0^2 (2x+1)dx=[x^2+x]_0^2=6$', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-l1'), (select id from public.learn_skills where code = 'm.h3.int') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-l2', (select id from public.learn_units where code = 'math-h3-unit'), '정적분의 활용', '넓이는 $|f(x)|$ 를 적분해요. 그래프가 $x$축 아래에 있는 부분은 따로 나누고, 두 곡선 사이는 (위)−(아래)를 적분해요. 속도의 적분은 이동한 거리예요.', '$y=6x-x^2$ 과 $x$축 사이의 넓이 $=36$', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-l2'), (select id from public.learn_skills where code = 'm.h3.area') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-l3', (select id from public.learn_units where code = 'math-h3-unit'), '등비급수', '$|r|<1$ 이면 $\sum ar^{n-1}=\frac{a}{1-r}$ 로 수렴하고, $|r|\ge 1$ 이면 발산해요. 순환소수와 되풀이되는 운동에 쓰여요.', '$3+\frac32+\frac34+\cdots=6$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-l3'), (select id from public.learn_skills where code = 'm.h3.ser') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-l4', (select id from public.learn_units where code = 'math-h3-unit'), '조건부확률과 독립', '$P(B\mid A)=\frac{P(A\cap B)}{P(A)}$. 독립이면 $P(A\cap B)=P(A)P(B)$ 이고, 독립시행은 $_nC_k\,p^k(1-p)^{n-k}$ 예요.', '$P(B\mid A)=\dfrac{0.2}{0.5}=0.4$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-l4'), (select id from public.learn_skills where code = 'm.h3.cond') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-l5', (select id from public.learn_units where code = 'math-h3-unit'), '이항분포와 정규분포', '$B(n,p)$ 의 평균은 $np$, 분산은 $np(1-p)$ 예요. 정규분포는 $Z=\frac{X-m}{\sigma}$ 로 표준화하고, 평균에 대하여 대칭이에요.', '$X\sim N(50,10^2)$ 이면 $P(X\ge 60)=P(Z\ge 1)$', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-l5'), (select id from public.learn_skills where code = 'm.h3.norm') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-geo1', (select id from public.learn_units where code = 'math-h3-unit'), '이차곡선', '포물선 $y^2=4px$의 초점은 $(p,0)$, 타원 $\frac{x^2}{a^2}+\frac{y^2}{b^2}=1$에서 $c^2=a^2-b^2$, 쌍곡선에서 $c^2=a^2+b^2$이에요.', '$y^2=12x$: 초점 $(3,0)$', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-geo1'), (select id from public.learn_skills where code = 'm.h3.geo1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-geo2', (select id from public.learn_units where code = 'math-h3-unit'), '평면벡터', '벡터 $(x,y)$의 크기는 $\sqrt{x^2+y^2}$, 내적은 $x_1x_2+y_1y_2$이고 두 벡터가 수직이면 내적이 0이에요.', '$(3,4)$의 크기: 5', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-geo2'), (select id from public.learn_skills where code = 'm.h3.geo2') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-pro1', (select id from public.learn_units where code = 'math-h3-unit'), '확률의 덧셈정리와 여사건', '$P(A\cup B)=P(A)+P(B)-P(A\cap B)$예요. 여사건의 확률은 $P(A^c)=1-P(A)$예요.', '$P(A)=0.5,\ P(B)=0.4,\ P(A\cap B)=0.2 \Rightarrow P(A\cup B)=0.7$', 7, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-pro1'), (select id from public.learn_skills where code = 'm.h3.pro1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-cal1', (select id from public.learn_units where code = 'math-h3-unit'), '여러 가지 함수의 미분', '합성함수는 (겉함수의 미분)×(속함수의 미분), 몫은 $\left(\frac{u}{v}\right)''=\frac{u''v-uv''}{v^2}$로 미분해요. $(e^x)''=e^x$, $(\ln x)''=\frac{1}{x}$, $(\sin x)''=\cos x$, $(\cos x)''=-\sin x$예요.', '$f(x)=e^{2x}$이면 $f''(x)=2e^{2x}$, $f''(0)=2$', 8, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-cal1'), (select id from public.learn_skills where code = 'm.h3.cal1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-h3-cnt1', (select id from public.learn_units where code = 'math-h3-unit'), '중복순열·중복조합과 이항정리', '중복을 허락하여 일렬로 나열하는 **중복순열**의 수는 (가짓수)를 (자리 수)번 곱한 값이에요. 같은 것이 있는 순열은 전체의 팩토리얼을 같은 것의 팩토리얼로 나누고, **중복조합**은 $_nH_r={}_{n+r-1}C_r$예요. $(x+1)^n$에서 $x^k$의 계수는 $_nC_k$예요.', 'aabbc를 나열하는 방법은 $5!\div(2!\times2!)=30$가지', 9, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-h3-cnt1'), (select id from public.learn_skills where code = 'm.h3.cnt1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-econ-u1', (select id from public.learn_courses where code = 'math-el-econ'), '수와 경제, 함수와 경제', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-econ1', (select id from public.learn_units where code = 'math-el-econ-u1'), '이자, 환율, 세금', '단리 이자=원금×이율×기간, 복리는 원금×(1+이율)^기간이에요. 환율은 외화 1단위의 값이고, 세금은 가격에 비율을 곱해요.', '10000원, 연 10% 복리 2년 → 12100원', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-econ1'), (select id from public.learn_skills where code = 'm.el.econ1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-econ2', (select id from public.learn_units where code = 'math-el-econ-u1'), '수요·공급과 최적화', '수요와 공급 곡선이 만나는 곳이 균형이에요. 수입 R=pq의 최대와 탄력성은 함수와 미분으로 구해요.', '100−2q=10+q → q=30', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-econ2'), (select id from public.learn_skills where code = 'm.el.econ2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-ai-u1', (select id from public.learn_courses where code = 'math-el-ai'), '데이터 처리, 예측과 최적화', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-ai1', (select id from public.learn_units where code = 'math-el-ai-u1'), '텍스트와 이미지 데이터', '문서는 단어의 빈도수 벡터로, 이미지는 화소 값의 행렬로 나타내요. 벡터의 내적이 클수록 문서가 비슷해요.', '(2,0,1)·(1,3,2)=4', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-ai1'), (select id from public.learn_skills where code = 'm.el.ai1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-ai2', (select id from public.learn_units where code = 'math-el-ai-u1'), '예측과 최적화', '추세선의 기울기, 오차의 제곱의 평균(손실), 경사하강법 $x_{새}=x-\eta f''(x)$로 예측을 개선해요.', '$f(x)=x^2$, x=4, η=0.1 → 3.2', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-ai2'), (select id from public.learn_skills where code = 'm.el.ai2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-job-u1', (select id from public.learn_courses where code = 'math-el-job'), '수와 단위, 비와 넓이, 경우의 수', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-job1', (select id from public.learn_units where code = 'math-el-job-u1'), '단위 환산과 비율', '1 m=100 cm, 1 kg=1000 g, 1시간=60분이에요. 할인 가격=가격×(1−할인율), 비 a:b로 섞으면 A는 전체의 $\frac{a}{a+b}$예요.', '3.5 m=350 cm', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-job1'), (select id from public.learn_skills where code = 'm.el.job1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-job2', (select id from public.learn_units where code = 'math-el-job-u1'), '넓이, 경우의 수, 증가율', '넓이로 필요한 재료의 양을 구하고, 곱의 법칙으로 가능한 짝의 수를, (늘어난 양)÷(처음 값)×100으로 증가율을 구해요.', '셔츠 4벌, 바지 3벌 → 12가지', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-job2'), (select id from public.learn_skills where code = 'm.el.job2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-cul-u1', (select id from public.learn_courses where code = 'math-el-cul'), '예술과 생활, 사회와 환경', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-cul1', (select id from public.learn_units where code = 'math-el-cul-u1'), '예술과 생활 속의 수학', '황금비 약 1.618, 한 옥타브 위의 음은 진동수가 2배, 점자 6개 점의 경우의 수는 $2^6-1=63$, 과반수는 전체의 절반을 넘는 수예요.', '440 Hz → 880 Hz', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-cul1'), (select id from public.learn_skills where code = 'm.el.cul1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-cul2', (select id from public.learn_units where code = 'math-el-cul-u1'), '사회와 환경 속의 수학', '자료의 평균과 증가율로 사회와 환경 문제를 수학적으로 분석해요. 증가율=(늘어난 양)÷(처음 값)×100.', '40에서 50으로 → 25% 증가', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-cul2'), (select id from public.learn_skills where code = 'm.el.cul2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-sta-u1', (select id from public.learn_courses where code = 'math-el-sta'), '자료와 표본, 추정과 검정', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-sta1', (select id from public.learn_units where code = 'math-el-sta-u1'), '통계적 문제와 표본', '표준편차는 편차의 제곱의 평균(분산)의 제곱근이에요. 표본은 임의추출, 층화추출, 집락추출, 계통추출 등으로 뽑아요.', '2, 4, 4, 4, 5, 5, 7, 9의 표준편차는 2', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-sta1'), (select id from public.learn_skills where code = 'm.el.sta1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-sta2', (select id from public.learn_units where code = 'math-el-sta-u1'), '추정과 가설검정', '95% 신뢰구간의 오차 한계는 $1.96\times\frac{σ}{\sqrt{n} }$이에요. 검정통계량 $z=\frac{\bar{x}-\mu}{σ/\sqrt{n} }$의 절댓값이 1.96보다 크면 5% 유의수준에서 귀무가설을 기각해요.', 'σ=10, n=100 → 오차 한계 1.96', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-sta2'), (select id from public.learn_skills where code = 'm.el.sta2') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-el-res-u1', (select id from public.learn_courses where code = 'math-el-res'), '탐구 방법, 절차와 윤리', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-res1', (select id from public.learn_units where code = 'math-el-res-u1'), '탐구 방법', '수학과제 탐구는 문헌 조사, 사례 조사, 수학 실험, 개발 연구 같은 방법으로 해요.', '직접 주사위를 던져 규칙 찾기 → 수학 실험', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-res1'), (select id from public.learn_skills where code = 'm.el.res1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-el-res2', (select id from public.learn_units where code = 'math-el-res-u1'), '탐구 절차와 연구 윤리', '탐구는 주제 선정 → 계획 → 수행 → 발표 → 반성의 순서로 해요. 출처를 밝히고 결과를 조작하지 않는 것이 연구 윤리예요.', '주제를 정한 다음은 탐구 계획', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-el-res2'), (select id from public.learn_skills where code = 'm.el.res2') on conflict do nothing;
