insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e2-u1', (select id from public.learn_courses where code = 'english-e2'), '동물, 동작, I like·I have, 짧은 문장, 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e2-l1', (select id from public.learn_units where code = 'english-e2-u1'), '동물과 사물 이름', 'rabbit(토끼), bird(새), fish(물고기)처럼 이름을 나타내는 낱말을 **명사**라고 해요.', '🐰 = rabbit', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e2-l1'), (select id from public.learn_skills where code = 'e.e2.noun') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e2-l2', (select id from public.learn_units where code = 'english-e2-u1'), '움직임을 나타내는 말', 'jump(점프하다), run(달리다), eat(먹다)처럼 움직임을 나타내는 낱말을 **동사**라고 해요.', 'I eat an apple.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e2-l2'), (select id from public.learn_skills where code = 'e.e2.verb') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e2-l3', (select id from public.learn_units where code = 'english-e2-u1'), 'I like / I have', '**I like ...**은 ''나는 ...을 좋아해요'', **I have ...**는 ''나는 ...이 있어요''예요.', 'I like dogs. I have a cat.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e2-l3'), (select id from public.learn_skills where code = 'e.e2.like') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e2-l4', (select id from public.learn_units where code = 'english-e2-u1'), '짧은 문장 만들기', 'I 다음에는 **am**, You 다음에는 **are**를 써요. 문장은 ''누가 → 어떻다/한다'' 순서예요.', 'I am a student. You are kind.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e2-l4'), (select id from public.learn_skills where code = 'e.e2.sent') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e2-l5', (select id from public.learn_units where code = 'english-e2-u1'), '짧은 글 읽기', '글을 읽을 때는 질문의 낱말을 글에서 먼저 찾아보세요.', 'Mina has a cat. → 고양이', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e2-l5'), (select id from public.learn_skills where code = 'e.e2.read') on conflict do nothing;
