insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e3-u1', (select id from public.learn_courses where code = 'english-e3'), '문장 만들기, 대명사, 현재와 과거, 하루 일과, 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l1', (select id from public.learn_units where code = 'english-e3-u1'), '문장 만들기', '문장은 ''누가 → 무엇을 한다 → 무엇'' 순서예요. He, She, 사람 이름 뒤의 동사에는 **-s**를 붙여요.', 'She reads a book.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l1'), (select id from public.learn_skills where code = 'e.e3.build') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l2', (select id from public.learn_units where code = 'english-e3-u1'), '대명사', '이름 대신 **He**(그), **She**(그녀), **It**(그것), **They**(그들), **We**(우리)를 쓸 수 있어요.', 'Tom is tall. He is tall.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l2'), (select id from public.learn_skills where code = 'e.e3.pron') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l3', (select id from public.learn_units where code = 'english-e3-u1'), '현재형과 과거형', '지금이나 반복되는 일은 **현재형**, 지난 일은 동사 끝에 **-ed**를 붙인 **과거형**을 써요.', 'I walk. → I walked.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l3'), (select id from public.learn_skills where code = 'e.e3.tense') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l4', (select id from public.learn_units where code = 'english-e3-u1'), '하루 일과', 'get up, brush my teeth, eat breakfast, go to bed... 하루 일과를 영어로 말해 보세요.', 'I get up at seven.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l4'), (select id from public.learn_skills where code = 'e.e3.routine') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-l5', (select id from public.learn_units where code = 'english-e3-u1'), '글 이해하기', '글을 읽고 누가, 언제, 무엇을 했는지 찾아보세요.', 'Jin gets up at seven.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-l5'), (select id from public.learn_skills where code = 'e.e3.read') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-abc1', (select id from public.learn_units where code = 'english-e3-u1'), '알파벳 대문자와 소문자', '알파벳에는 **대문자**와 **소문자**가 있어요. 모양이 다른 짝이 많으니 하나씩 짝을 지어 기억해요. b, d, p, q처럼 비슷한 글자는 특히 조심해요.', 'A–a, B–b, D–d, G–g', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-abc1'), (select id from public.learn_skills where code = 'e.e3.abc1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e3-snd1', (select id from public.learn_units where code = 'english-e3-u1'), '소리와 철자의 관계', '낱말의 첫소리와 첫 글자는 서로 관계가 있어요. 같은 소리로 시작하는 낱말을 찾으며 소리와 철자의 관계를 익혀요. ph처럼 두 글자가 f 소리를 내기도 해요.', 'cat → cup, fish → fan', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e3-snd1'), (select id from public.learn_skills where code = 'e.e3.snd1') on conflict do nothing;
