insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e5-u1', (select id from public.learn_courses where code = 'english-e5'), '관사와 복수형, 비교, 미래, 문장 바꿔 쓰기, 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l1', (select id from public.learn_units where code = 'english-e5-u1'), '관사·복수형·There is/are', '모음 소리 앞에는 **an**, 자음 소리 앞에는 **a**를 써요. 하나면 **There is**, 여러 개면 **There are**를 써요.', 'an apple, two boxes, There are three books.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l1'), (select id from public.learn_skills where code = 'e.e5.gram') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l2', (select id from public.learn_units where code = 'english-e5-u1'), '비교하는 말', '둘을 비교할 때는 **-er + than**, 가장 ~한 것은 **the -est**를 써요. 긴 낱말은 **more**를 써요.', 'Tom is taller than Ben.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l2'), (select id from public.learn_skills where code = 'e.e5.comp') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l3', (select id from public.learn_units where code = 'english-e5-u1'), '미래 표현', '앞으로 할 일은 **will + 동사원형** 또는 **be going to + 동사원형**으로 말해요.', 'I am going to visit Jeju.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l3'), (select id from public.learn_skills where code = 'e.e5.future') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l4', (select id from public.learn_units where code = 'english-e5-u1'), '문장 바꿔 쓰기', '부정문은 **not / don''t / doesn''t / didn''t**를, 의문문은 **Are / Do / Does**를 문장 앞에 써요.', 'I am happy. → I am not happy.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l4'), (select id from public.learn_skills where code = 'e.e5.transform') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e5-l5', (select id from public.learn_units where code = 'english-e5-u1'), '글 이해하기', '긴 글은 누가·어디·언제·무엇을에 밑줄을 치듯 찾아 읽으면 쉬워요.', 'Ken lives in Busan.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e5-l5'), (select id from public.learn_skills where code = 'e.e5.read') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('english-e6-u1', (select id from public.learn_courses where code = 'english-e6'), '시제 총정리, 조동사, 낱말, 이어 주는 말, 문단 읽기', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l1', (select id from public.learn_units where code = 'english-e6-u1'), '시제 총정리', '지금 하는 일은 **be + -ing**, 지난 일은 **과거형**, 앞으로 할 일은 **will / be going to**로 말해요.', 'The baby is sleeping now.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l1'), (select id from public.learn_skills where code = 'e.e6.tense') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l2', (select id from public.learn_units where code = 'english-e6-u1'), 'can, must, should, may', '**can**(할 수 있다), **must**(해야 한다), **should**(하는 게 좋다), **may**(해도 된다) 다음에는 동사원형이 와요.', 'You should brush your teeth.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l2'), (select id from public.learn_skills where code = 'e.e6.modal') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l3', (select id from public.learn_units where code = 'english-e6-u1'), '낱말 넓히기', '비슷한 뜻의 낱말과 반대말을 함께 익히면 낱말이 두 배로 늘어요.', 'big ≈ large, happy ↔ sad', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l3'), (select id from public.learn_skills where code = 'e.e6.vocab') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l4', (select id from public.learn_units where code = 'english-e6-u1'), '이어 주는 말', '**because**(이유), **so**(결과), **but**(반대), **if**(만약), **when**(~할 때)으로 문장을 이어요.', 'I was tired, so I went to bed early.', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l4'), (select id from public.learn_skills where code = 'e.e6.clause') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-l5', (select id from public.learn_units where code = 'english-e6-u1'), '문단 읽기', '여러 문장으로 된 글을 읽고 누가·언제·왜 했는지 찾아 답해요.', 'Jina was tired because they walked a lot.', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-l5'), (select id from public.learn_skills where code = 'e.e6.read') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-seq1', (select id from public.learn_units where code = 'english-e6-u1'), '일이 일어난 순서 파악하기', '**First**(먼저), **Then / Next**(그다음), **After that**(그 후에), **Finally**(마지막으로)처럼 순서를 나타내는 말을 찾으면 일이 일어난 순서를 알 수 있어요.', 'First, I wake up. Then I eat breakfast. Finally, I go to school.', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-seq1'), (select id from public.learn_skills where code = 'e.e6.seq1') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-e6-pun1', (select id from public.learn_units where code = 'english-e6-u1'), '대문자와 문장 부호', '문장은 **대문자**로 시작하고 끝에는 알맞은 **문장 부호**를 써요. 보통 문장은 마침표(.), 질문은 물음표(?), 놀람이나 강한 느낌은 느낌표(!)를 써요. 사람 이름과 I는 항상 대문자예요.', 'Is this your bag? Yes, it is.', 6, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-e6-pun1'), (select id from public.learn_skills where code = 'e.e6.pun1') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('en-m1-unit1', (select id from public.learn_courses where code = 'en-m1-basics'), '단어와 기초 문법', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l1', (select id from public.learn_units where code = 'en-m1-unit1'), '일상 단어 익히기', '자주 쓰는 단어는 **소리 + 뜻 + 쓰기**를 함께 익히면 오래 기억돼요. 스피커 버튼으로 발음을 들어 보세요.', 'library = 도서관 / desk = 책상 / milk = 우유', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l1'), (select id from public.learn_skills where code = 'e.vocab') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l2', (select id from public.learn_units where code = 'en-m1-unit1'), 'be동사 am / are / is', 'be동사는 주어에 따라 모양이 달라져요. **I → am**, **he / she / it → is**, **you / we / they → are**.', 'I am a student. She is my friend. They are in the classroom.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l2'), (select id from public.learn_skills where code = 'e.be') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l3', (select id from public.learn_units where code = 'en-m1-unit1'), '일반동사 현재형', '주어가 **he / she / it(3인칭 단수)** 이면 동사에 **-s / -es**를 붙여요. -ch, -sh, -s, -x, -o 로 끝나면 -es, 자음+y는 y를 i로 바꾸고 -es!', 'go → goes / watch → watches / study → studies', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l3'), (select id from public.learn_skills where code = 'e.pres') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-l4', (select id from public.learn_units where code = 'en-m1-unit1'), '복수형과 문장 만들기', '명사가 둘 이상이면 보통 **-s**를 붙이고, -x로 끝나면 **-es**, 불규칙 복수형은 따로 외워요. 문장은 **주어 → 동사 → 나머지** 순서예요.', 'book → books / box → boxes / child → children', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l4'), (select id from public.learn_skills where code = 'e.plural') on conflict do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-l4'), (select id from public.learn_skills where code = 'e.order') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('en-m2-unit', (select id from public.learn_courses where code = 'en-m2-grammar-reading'), '중2 영어', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l1', (select id from public.learn_units where code = 'en-m2-unit'), '현재완료', 'have/has + 과거분사. 경험, 완료, 계속을 나타내고, since(시점)와 for(기간)를 구별해요.', 'I have lived here for five years.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l1'), (select id from public.learn_skills where code = 'e.m2.perf') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l2', (select id from public.learn_units where code = 'en-m2-unit'), '수동태', 'be + 과거분사로 ''~되다/당하다'' 를 나타내요. 행위자는 by 로 덧붙여요.', 'The room is cleaned by Mina.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l2'), (select id from public.learn_skills where code = 'e.m2.pass') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l3', (select id from public.learn_units where code = 'en-m2-unit'), 'to부정사와 동명사', 'want, hope, decide + to부정사, enjoy, finish, avoid + 동명사. stop + to V 는 목적, stop + V-ing 는 중단이에요.', 'I want to buy a bike. She enjoys singing.', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l3'), (select id from public.learn_skills where code = 'e.m2.inf') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l4', (select id from public.learn_units where code = 'en-m2-unit'), '비교급과 최상급', '-er/-est 와 more/most. 비교급에는 than, 최상급에는 the 를 써요. good → better → best 는 불규칙이에요.', 'hot → hotter → the hottest', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l4'), (select id from public.learn_skills where code = 'e.m2.comp') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-l5', (select id from public.learn_units where code = 'en-m2-unit'), '독해: 주제와 세부 정보', '질문을 먼저 읽고 단서 문장을 찾아요. 제목과 요지는 글 전체를 아우르는 내용이에요.', 'As a result = 그 결과', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-l5'), (select id from public.learn_skills where code = 'e.m2.read') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m2-sum1', (select id from public.learn_units where code = 'en-m2-unit'), '글의 내용 요약하기', '글을 요약할 때는 **중심 내용**을 찾아 한두 문장으로 줄여요. 세부 내용 하나만 말하거나, 글에 없는 내용을 더하거나, 너무 넓게 말한 문장은 좋은 요약이 아니에요.', 'Recycling saves resources and reduces trash.', 5, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m2-sum1'), (select id from public.learn_skills where code = 'e.m2.sum1') on conflict do nothing;
