insert into public.learn_units(code, course_id, title, sort_order, status) values ('en-m3-unit', (select id from public.learn_courses where code = 'en-m3-grammar-reading'), '중3 영어', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m3-l1', (select id from public.learn_units where code = 'en-m3-unit'), '관계대명사', 'who(사람), which(사물), that(둘 다), whose(소유)로 두 문장을 하나로 이어요.', 'I have a friend who lives in Canada.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m3-l1'), (select id from public.learn_skills where code = 'e.m3.rel') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m3-l2', (select id from public.learn_units where code = 'en-m3-unit'), '조건문과 가정법 과거', 'If + 현재, will + V (가능한 일). If + 과거, would + V (현재와 반대되는 가정).', 'If I were rich, I would travel.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m3-l2'), (select id from public.learn_skills where code = 'e.m3.cond') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m3-l3', (select id from public.learn_units where code = 'en-m3-unit'), '간접의문문', '의문사 + 주어 + 동사 순서로 써요. do/does/did 를 쓰지 않아요.', 'Do you know where he lives?', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m3-l3'), (select id from public.learn_skills where code = 'e.m3.ques') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m3-l4', (select id from public.learn_units where code = 'en-m3-unit'), '분사', '-ing 는 능동·진행, -ed 는 수동·완료. 감정은 일으키면 -ing, 느끼면 -ed 예요.', 'an exciting game / I am excited', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m3-l4'), (select id from public.learn_skills where code = 'e.m3.part') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-m3-l5', (select id from public.learn_units where code = 'en-m3-unit'), '독해: 추론과 글의 목적', '단서를 조합해 추론하고, 글의 목적은 요청·주장을 보고 정해요.', 'Could you tell me ...? → 질문(문의)', 4, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-m3-l5'), (select id from public.learn_skills where code = 'e.m3.read') on conflict do nothing;
insert into public.learn_courses(code, curriculum_id, subject_id, school_level, grade, title, world_name, world_emoji, world_tagline, elective, sort_order, status)
insert into public.learn_units(code, course_id, title, sort_order, status) values ('en-h1-unit', (select id from public.learn_courses where code = 'en-h1-grammar-reading'), '고1 영어', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-h1-l1', (select id from public.learn_units where code = 'en-h1-unit'), '완료시제와 완료진행', 'had + p.p. 는 과거보다 앞선 일, have been -ing 는 지금까지 계속되는 동작이에요.', 'I have been waiting for an hour.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'en-h1-l1'), (select id from public.learn_skills where code = 'e.h1.tense') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-h1-l2', (select id from public.learn_units where code = 'en-h1-unit'), '관계부사와 명사절', 'where / when / why 는 부사 역할의 관계사이고, whether / that 은 명사절을 이끌어요.', 'This is the town where I was born.', 1, 'PUBLISHED') on conflict (code) do nothing;
