insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('en-h1-l3', (select id from public.learn_units where code = 'en-h1-unit'), '분사구문', '접속사와 주어를 줄이고 동사를 -ing 로 바꿔요. 의미상 주어가 같아야 해요.', 'Feeling sick, I went home.', 2, 'PUBLISHED') on conflict (code) do nothing;
